hl.monitor({
    output   = "eDP-1",
    mode     = "1920x1080@144",
    position = "0x0",
    scale    = 1,
})

-- toggle floating

hl.bind("SUPER" .. " + " .. "V", hl.dsp.window.float())

-- toggle/manage windows 

hl.bind("SUPER" .. " + " .. "SPACE", hl.dsp.exec_cmd("rofi -show"))

hl.bind("SUPER" .. " + " .. "W", hl.dsp.window.close())

