-- cycle focus

hl.bind("SUPER" .. " + " .. "TAB", hl.dsp.window.cycle_next())

hl.bind("SUPER + SHIFT" .. " + " .. "TAB", hl.dsp.window.cycle_next({ next = false }))

--toggle fullscreen

hl.bind("SUPER" .. " + " .. "F", hl.dsp.window.fullscreen())

-- toggle workspaces

--bind = SUPER, 1, workspace, 1

