hl.bind("SUPER" .. " + " .. "S", hl.dsp.workspace.toggle_special(nil))

hl.bind("SUPER + SHIFT" .. " + " .. "S", hl.dsp.window.move({ workspace = "special" }))

-- bind for launching terminal

hl.bind("SUPER" .. " + " .. "RETURN", hl.dsp.exec_cmd("kitty"))

