-- top(fn) button binds

hl.bind("SUPER" .. " + " .. "code:73", hl.dsp.exec_cmd("brightnessctl set 10-"))

hl.bind("SUPER" .. " + " .. "code:74", hl.dsp.exec_cmd("brightnessctl set +10"))

local curSoundCard = "$(h510-detect)"


hl.bind("SUPER" .. " + " .. "code:122", hl.dsp.exec_cmd("amixer -c $(h510-detect) sset PCM,1 10%- & amixer -c $(h510-detect) sset PCM,0 10%- & mpv/usr/share/sounds/ocean/stereo/audio-volume-change.oga"))

hl.bind("SUPER" .. " + " .. "code:123", hl.dsp.exec_cmd("amixer -c $(h510-detect) sset PCM,1 10%+ & amixer -c $(h510-detect) sset PCM,0 10%+ & mpv/usr/share/sounds/ocean/stereo/audio-volume-change.oga"))

-- touchpad input fix

hl.config({
    input = {
        kb_layout = "pl",
    },
})

hl.bind("SUPER" .. " + " .. "PRINT", hl.dsp.exec_cmd("hyprshot -m window"))

-- Screenshot a monitor

hl.bind("PRINT", hl.dsp.exec_cmd("hyprshot -m output"))

-- Screenshot a region

hl.bind("SHIFT" .. " + " .. "PRINT", hl.dsp.exec_cmd("hyprshot -m region"))

hl.window_rule({
    name  = "LocalModel",
    match = {
        class = "LocalModel",
    },
    no_blur = true,
    no_dim = true,
    no_shadow = true,
    float = true,
    pin = true,
    no_focus = true,
})

hl.window_rule({
    name  = "upwork",
    match = {
        class = "Upwork",
    },
    allows_input = true,
    float = true,
    pin = true,
})

-- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd("[workspace 1] kitty")
    hl.exec_cmd("[workspace 1] firefox")
    hl.exec_cmd("amixer -c $(h510-detect) sset PCM,1 18% & amixer -c $(h510-detect) sset PCM,0 18%")
end)
